#!/usr/bin/env sh
set -eu

cd "$(dirname "$0")/.."

# The flat view already fetches these three modules. Keep their URLs shared.
npm exec --yes --package=esbuild@0.28.2 -- esbuild src/scenes.js \
  --bundle --format=esm --platform=browser --target=es2022 --minify \
  --alias:three=./vendor/three/build/three.module.js \
  --external:./geo-model.js --external:./flow-model.js '--external:./relief-image.js?v=5' \
  --legal-comments=inline \
  --banner:js='/* Generated by scripts/build-three.sh. Three.js r187, MIT license: vendor/three/LICENSE. */' \
  --outfile=src/three-runtime.js
